CREATE TABLE IF NOT EXISTS "PUBLIC"."PRODUCT_OFFER"
(
    "IN_STOCK"     BOOLEAN,
    "PRICE"        NUMERIC(38, 2),
    "CART_ITEM_ID" BIGINT,
    "FETCHED_AT"   TIMESTAMP(6)              NOT NULL,
    "ID"           BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1 RESTART WITH 50) NOT NULL,
    "SHOP_ID"      BIGINT,
    "SHOP_NAME"    CHARACTER VARYING(50)     NOT NULL,
    "PRODUCT_NAME" CHARACTER VARYING(200)    NOT NULL,
    "PRODUCT_URL"  CHARACTER VARYING(200)    NOT NULL,
    "SEARCH_QUERY" CHARACTER VARYING(200),
    "SOURCE"       ENUM ('WEB_SCRAPING')
);

ALTER TABLE "PUBLIC"."PRODUCT_OFFER"
    ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4" PRIMARY KEY ("ID");

